284	    @Override
285	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
286	        Owner owner = this.clinicService.findOwnerById(ownerId);
287	        if (owner != null) {
288	            Pet pet = owner.getPet(petId);
289	            if (pet != null) {
290	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
291	            }
292	        }
293	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	    }
295	
296	    /**
297	     * Counts how many existing owners share the given first and last name, compared
298	     * case-insensitively, at the moment before the new owner is persisted. The result is
299	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
300	     * stood when the owner was created rather than being recomputed on later reads.
301	     *
302	     * @param firstName the first name of the owner being created
303	     * @param lastName the last name of the owner being created
304	     * @return the number of pre-existing owners with the same first and last name
305	     */
306	    private int countNamesakes(String firstName, String lastName) {
307	        String first = firstName == null ? "" : firstName;
308	        String last = lastName == null ? "" : lastName;
309	        return (int) this.clinicService.findAllOwners().stream()
310	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
311	                && last.equalsIgnoreCase(existing.getLastName()))
312	            .count();
313	    }
314	
315	    /**
316	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
317	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
318	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
319	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
320	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
321	     *
322	     * <p>When the computed code collides with an existing owner's customer code, it is de-duplicated
323	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result
324	     * unique across all existing owners' customer codes. The de-duplicated code is what gets assigned.
325	     *
326	     * @param owner the owner being created, whose postcode, city and last name feed the code
327	     * @param normalizedTelephone the owner's E.164-normalized telephone
328	     * @return the assigned customer code, de-duplicated against existing owners if necessary
329	     */
330	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
331	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
332	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
333	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
334	        String baseCode = region + "-" + hash8;
335	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
336	            .map(Owner::getCustomerCode)
337	            .filter(code -> code != null)
338	            .collect(java.util.stream.Collectors.toSet());
339	        if (!existingCodes.contains(baseCode)) {
340	            return baseCode;
341	        }
342	        int n = 2;
343	        while (existingCodes.contains(baseCode + "-" + n)) {
344	            n++;
345	        }
346	        return baseCode + "-" + n;
347	    }
348	
349	    /**
350	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
351	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
352	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
353	     *
354	     * @param postcode the owner's postcode, may be {@code null}
355	     * @param city the owner's city, used to resolve the region when the postcode does not
356	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
357	     */
358	    private String deriveRegion(String postcode, String city) {
359	        if (postcode != null) {
360	            try {
361	                int value = Integer.parseInt(postcode.trim());
362	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
363	                    int[] range = entry.getValue();
364	                    if (value >= range[0] && value <= range[1]) {
365	                        return entry.getKey();
366	                    }
367	                }
368	            } catch (NumberFormatException ex) {
369	                // Not a numeric postcode; fall back to the city table below.
370	            }
371	        }
372	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
373	    }
374	
375	    /**
376	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
377	     * given input's UTF-8 bytes.
378	     *
379	     * @param input the string to hash
380	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
381	     */
382	    private String sha256Hex8(String input) {
383	        try {
384	            byte[] digest = MessageDigest.getInstance("SHA-256")
385	                .digest(input.getBytes(StandardCharsets.UTF_8));
386	            StringBuilder hex = new StringBuilder();
387	            for (int i = 0; i < 4; i++) {
388	                hex.append(String.format("%02X", digest[i]));
389	            }
390	            return hex.toString();
391	        } catch (NoSuchAlgorithmException ex) {
392	            throw new IllegalStateException("SHA-256 not available", ex);
393	        }
394	    }
395	
396	    /**
397	     * Rejects an owner payload that is missing or blank in any of the required fields
398	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
399	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
400	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
401	     * guard enforces the rule uniformly for every required field.
402	     *
403	     * @param ownerFieldsDto the submitted owner payload
404	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
405	     */
406	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
407	        List<String> invalidFields = new ArrayList<>();
408	        if (isBlank(ownerFieldsDto.getFirstName())) {
409	            invalidFields.add("firstName");
410	        }
411	        if (isBlank(ownerFieldsDto.getLastName())) {
412	            invalidFields.add("lastName");
413	        }
414	        if (isBlank(ownerFieldsDto.getAddressLine1())
415	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
416	            invalidFields.add("address");
417	        }
418	        if (isBlank(ownerFieldsDto.getCity())) {
419	            invalidFields.add("city");
420	        }
421	        if (isBlank(ownerFieldsDto.getTelephone())) {
422	            invalidFields.add("telephone");
423	        }
424	        if (!invalidFields.isEmpty()) {
425	            throw new InvalidOwnerFieldsException(invalidFields);
426	        }
427	    }
428	
429	    private boolean isBlank(String value) {
430	        return value == null || value.isBlank();
431	    }
432	
433	    /**
434	     * Whether an existing owner has been soft-deleted. A soft-deleted owner retains its row but is
435	     * excluded from the create endpoint's duplicate and identity checks, so it never blocks the
436	     * creation of a new owner. A {@code null} flag (an owner predating the soft-delete column) is
437	     * treated as not deleted.
438	     *
439	     * @param owner an existing owner
440	     * @return {@code true} if the owner is flagged deleted
441	     */
442	    private boolean isDeleted(Owner owner) {
443	        return Boolean.TRUE.equals(owner.getDeleted());
444	    }
445	
446	    /**
447	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
448	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
449	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
450	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
451	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
452	     * and returned exactly as given.
453	     *
454	     * @param postcode the submitted postcode, may be {@code null} when absent
455	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
456	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
457	     */
458	    private void validatePostcode(String postcode, String city) {
459	        if (postcode == null) {
460	            return;
461	        }
462	        if (!postcode.matches("[0-9]{4}")) {
463	            throw new InvalidOwnerFieldsException(List.of("postcode"));
464	        }
465	        String region = city == null ? null : CITY_REGION.get(city);
466	        if (region == null) {
467	            return;
468	        }
469	        int[] range = REGION_POSTCODES.get(region);
470	        int value = Integer.parseInt(postcode);
471	        if (value < range[0] || value > range[1]) {
472	            throw new InvalidOwnerFieldsException(List.of("postcode"));
473	        }
474	    }
475	
476	    /**
477	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
478	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
479	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
480	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
481	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
482	     *
483	     * @param telephone the raw telephone value from the submitted owner payload
484	     * @return the normalized E.164 telephone number
485	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
486	     */
487	    private String normalizeTelephone(String telephone) {
488	        String raw = telephone == null ? "" : telephone.strip();
489	        boolean hasCountryCode = raw.startsWith("+");
490	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
491	        String digits;
492	        if (hasCountryCode) {
493	            digits = cleaned.substring(1);
494	        } else {
495	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
496	            digits = "61" + national;
497	        }
498	        if (!digits.matches("[0-9]{8,15}")) {
499	            throw new InvalidOwnerFieldsException(List.of("telephone"));
500	        }
501	        validateNationalNumberLength(digits);
502	        return "+" + digits;
503	    }
504	
505	    /**
506	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
507	     * country calling code) has the exact length required for that country. The country code is matched
508	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
509	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
510	     *
511	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
512	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
513	     */
514	    private void validateNationalNumberLength(String digits) {
515	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
516	            String countryCode = entry.getKey();
517	            if (digits.startsWith(countryCode)) {
518	                int nationalLength = digits.length() - countryCode.length();
519	                if (nationalLength != entry.getValue()) {
520	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
521	                }
522	                return;
523	            }
524	        }
525	    }
526	
527	    /**
528	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
529	     * returning {@code null} when the value cannot form a valid E.164 number.
530	     *
531	     * @param telephone an existing owner's stored telephone value
532	     * @return the E.164 form, or {@code null} if it cannot be normalized
533	     */
534	    private String toE164OrNull(String telephone) {
535	        try {
536	            return normalizeTelephone(telephone);
537	        } catch (InvalidOwnerFieldsException ex) {
538	            return null;
539	        }
540	    }
541	
542	    /**
543	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
544	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
545	     * accepted value is trimmed and lower-cased before it is stored and returned.
546	     *
547	     * @param email the raw email value from the submitted owner payload, may be {@code null}
548	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
549	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
550	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
551	     */
552	    private String normalizeEmail(String email) {
553	        if (email == null) {
554	            return null;
555	        }
556	        String trimmed = email.strip();
557	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
558	            throw new InvalidOwnerFieldsException(List.of("email"));
559	        }
560	        String normalized = trimmed.toLowerCase(Locale.ROOT);
561	        String domain = normalized.substring(normalized.indexOf('@') + 1);
562	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
563	            throw new InvalidOwnerFieldsException(List.of("email"));
564	        }
565	        return normalized;
566	    }
567	
568	    /**
569	     * Rejects creating an owner that would be a second member of an existing household. The household
570	     * is keyed on {@code (lastName, postcode)} through the deterministic {@link #householdId}, so any
571	     * existing owner carrying the same {@code householdId} makes the owner being created a household
572	     * duplicate. Such an owner is rejected with a 409, <em>unless</em> the request opts into
573	     * {@code sharesHousehold}: a declared household member deliberately bypasses this block and is
574	     * created as an additional member of the household.
575	     *
576	     * @param owner the owner being created, whose computed household id is matched
577	     * @param sharesHousehold whether the request declared the owner a shared-household member
578	     * @throws DuplicateOwnerIdentityException if another owner already belongs to the same household
579	     */
580	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
581	        if (sharesHousehold) {
582	            return;
583	        }
584	        String householdId = owner.getHouseholdId();
585	        boolean duplicate = householdId != null && this.clinicService.findAllOwners().stream()
586	            .filter(existing -> !isDeleted(existing))
587	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
588	        if (duplicate) {
589	            throw new DuplicateOwnerIdentityException(householdId);
590	        }
591	    }
592	
593	    /**
594	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
595	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
596	     * owner that is not a hard duplicate but shares an existing owner's last name (compared
597	     * case-insensitively, see {@link #normalizeForComparison}) and postcode while carrying a <em>different</em>
598	     * telephone. When such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
599	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
600	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
601	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
602	     *
603	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the household
604	     * duplicate block) is never a <em>suspected</em> duplicate: it is knowingly created as another member
605	     * of the household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
606	     * {@code null} without consulting the existing population.
607	     *
608	     * @param owner the owner being created, whose last name and postcode are matched
609	     * @param normalizedTelephone the E.164 telephone of the owner being created
610	     * @param sharesHousehold whether the request declared the owner a shared-household member
611	     */
612	    private void assignPossibleDuplicate(Owner owner, String normalizedTelephone, boolean sharesHousehold) {
613	        if (sharesHousehold) {
614	            owner.setPossibleDuplicateOf(null);
615	            owner.setPossibleDuplicate(false);
616	            return;
617	        }
618	        String postcode = owner.getPostcode();
619	        Integer matchId = null;
620	        if (postcode != null) {
621	            String lastName = normalizeForComparison(owner.getLastName());
622	            for (Owner existing : this.clinicService.findAllOwners()) {
623	                if (!isDeleted(existing)
624	                    && postcode.equals(existing.getPostcode())
625	                    && lastName.equals(normalizeForComparison(existing.getLastName()))
626	                    && !normalizedTelephone.equals(toE164OrNull(existing.getTelephone()))
627	                    && existing.getId() != null
628	                    && (matchId == null || existing.getId() < matchId)) {
629	                    matchId = existing.getId();
630	                }
631	            }
632	        }
633	        owner.setPossibleDuplicateOf(matchId);
634	        owner.setPossibleDuplicate(matchId != null);
635	    }
636	
637	    /**
638	     * The maximum number of owners a single city may contain. Once a city already holds this many
639	     * owners, creating another owner in that city is rejected.
640	     */
641	    private static final int MAX_OWNERS_PER_CITY = 50;
642	
643	    /**
644	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
645	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
646	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
647	     * counting used elsewhere.
648	     *
649	     * @param city the city of the owner being created
650	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
651	     */
652	    /**
653	     * The maximum number of owners that may be registered on a single day. Once this many owners
654	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
655	     */
656	    private static final int MAX_OWNERS_PER_DAY = 100;
657	
658	    /**
659	     * Fixed list of public holidays. A registration date that lands on one of these dates is not a
660	     * business day and is rolled forward to the next non-holiday weekday.
661	     */
662	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
663	        LocalDate.of(2026, 1, 1),
664	        LocalDate.of(2026, 1, 26),
665	        LocalDate.of(2026, 4, 25),
666	        LocalDate.of(2026, 12, 25),
667	        LocalDate.of(2026, 12, 28));
668	
669	    /**
670	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
671	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
672	     * registration date of the owner being created.
673	     *
674	     * @param registrationDate the registration date of the owner being created
675	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
676	     */
677	    /**
678	     * Rolls an effective registration date forward onto a business day. A registration date must fall
679	     * on a weekday that is not a public holiday: when the supplied or defaulted date is a Saturday, a
680	     * Sunday, or a listed public holiday it is rolled forward one day at a time until it reaches the
681	     * next non-holiday business day, and that adjusted date becomes the owner's {@code registrationDate}.
682	     * A date that is already a non-holiday weekday is returned unchanged. Every value derived from the
683	     * registration date (the daily create-limit count, the membership number's year segment, and so on)
684	     * uses this adjusted date.
685	     *
686	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
687	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
688	     */
689	    /**
690	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
691	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
692	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
693	     * against the date exactly as supplied, before it is rolled forward onto a business day.
694	     *
695	     * @param registrationDate the registration date supplied in the request, may be {@code null}
696	     * @throws FutureRegistrationDateException if the supplied date is after the server date
697	     */
698	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
699	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
700	            throw new FutureRegistrationDateException(registrationDate);
701	        }
702	    }
703	
704	    private LocalDate rollToBusinessDay(LocalDate date) {
705	        LocalDate adjusted = date;
706	        while (!isBusinessDay(adjusted)) {
707	            adjusted = adjusted.plusDays(1);
708	        }
709	        return adjusted;
710	    }
711	
712	    private boolean isBusinessDay(LocalDate date) {
713	        DayOfWeek day = date.getDayOfWeek();
714	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
715	            return false;
716	        }
717	        return !PUBLIC_HOLIDAYS.contains(date);
718	    }
719	
720	    private void rejectDailyLimitReached(LocalDate registrationDate) {
721	        long ownersToday = this.clinicService.findAllOwners().stream()
722	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
723	            .count();
724	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
725	            throw new DailyOwnerLimitExceededException(registrationDate);
726	        }
727	    }
728	
729	    /**
730	     * The number of owners that must already share a {@code registrationDate} before a newly created
731	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
732	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
733	     */
734	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
735	
736	    /**
737	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
738	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
739	     * the same registration date at the time this owner is created. Existing owners are counted by their
740	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
741	     * daily create-limit accumulation.
742	     *
743	     * @param registrationDate the registration date of the owner being created
744	     * @return {@code true} if the day already holds more than the threshold number of owners
745	     */
746	    private boolean isBulkSignupDay(LocalDate registrationDate) {
747	        long ownersToday = this.clinicService.findAllOwners().stream()
748	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
749	            .count();
750	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
751	    }
752	
753	    private void rejectCityAtCapacity(String city) {
754	        String normalizedCity = normalizeForComparison(city);
755	        long ownersInCity = this.clinicService.findAllOwners().stream()
756	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
757	            .count();
758	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
759	            throw new OwnerCityCapacityExceededException(city);
760	        }
761	    }
762	
763	    /**
764	     * Counts how many owners belong to the household the owner being created has just been assigned to,
765	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
766	     * given identifier; the owner being created is added on because it is counted before being persisted.
767	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
768	     * household of one. The value is snapshotted on the owner.
769	     *
770	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
771	     * @return the number of household members, including the owner being created
772	     */
773	    private int countHousehold(String householdId) {
774	        if (householdId == null) {
775	            return 1;
776	        }
777	        long existing = this.clinicService.findAllOwners().stream()
778	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
779	            .count();
780	        return (int) existing + 1;
781	    }
782	
783	    /**
784	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
785	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
786	     * name is normalized for case- and whitespace-insensitive comparison (see
787	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
788	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
789	     * regardless of creation order, making them members of one household.
790	     *
791	     * @param lastName the owner's last name
792	     * @param postcode the owner's postcode, may be {@code null}
793	     * @return the deterministic household identifier
794	     */
795	    private String householdId(String lastName, String postcode) {
796	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
797	        try {
798	            byte[] digest = MessageDigest.getInstance("SHA-256")
799	                .digest(key.getBytes(StandardCharsets.UTF_8));
800	            StringBuilder hex = new StringBuilder();
801	            for (int i = 0; i < 6; i++) {
802	                hex.append(String.format("%02x", digest[i]));
803	            }
804	            return hex.toString();
805	        } catch (NoSuchAlgorithmException ex) {
806	            throw new IllegalStateException("SHA-256 not available", ex);
807	        }
808	    }
809	
810	    /**
811	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
812	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
813	     * result is lower-cased. A {@code null} value normalizes to the empty string.
814	     *
815	     * @param value the value to normalize, may be {@code null}
816	     * @return the normalized value
817	     */
818	    private String normalizeForComparison(String value) {
819	        if (value == null) {
820	            return "";
821	        }
822	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
823	    }
824	
825	    /**
826	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
827	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
828	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
829	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
830	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
831	     * that is stored, returned, and used for every address comparison (household duplicate detection
832	     * and the shared household id).
833	     *
834	     * @param address the raw address value from the submitted owner payload, may be {@code null}
835	     * @return the normalized address
836	     */
837	    /**
838	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
839	     * the structured fields over the flat {@code address} input for backward compatibility. When a
840	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
841	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
842	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
843	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
844	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
845	     *
846	     * @param owner the owner being created, whose raw address fields are normalized in place
847	     */
848	    private void applyAddress(Owner owner) {
849	        String line1 = owner.getAddressLine1();
850	        if (line1 != null && !line1.isBlank()) {
851	            String normalizedLine1 = normalizeAddress(line1);
852	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
853	            owner.setAddressLine1(normalizedLine1);
854	            if (!normalizedLine2.isEmpty()) {
855	                owner.setAddressLine2(normalizedLine2);
856	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
857	            } else {
858	                owner.setAddressLine2(null);
859	                owner.setAddress(normalizedLine1);
860	            }
861	        } else {
862	            owner.setAddressLine1(null);
863	            owner.setAddressLine2(null);
864	            owner.setAddress(normalizeAddress(owner.getAddress()));
865	        }
866	    }
867	
868	    private String normalizeAddress(String address) {
869	        if (address == null) {
870	            return "";
871	        }
872	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
873	        if (collapsed.isEmpty()) {
874	            return "";
875	        }
876	        String[] tokens = collapsed.split(" ");
877	        StringBuilder normalized = new StringBuilder();
878	        for (int i = 0; i < tokens.length; i++) {
879	            if (i > 0) {
880	                normalized.append(' ');
881	            }
882	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
883	        }
884	        return normalized.toString();
885	    }
886	}
